    private func route() throws -> Swap.Route {
        try JSONDecoder().decode(Swap.Route.self, from: Data(Self.routeJSON.utf8))
    }

    @Test func decodesTheLiveRoute() throws {
        let route = try route()
        #expect(route.hops.count == 4)
        #expect(route.path.compactMap(\.symbol) == ["STX", "WELSH", "CHA", "BOB", "sBTC"])
        #expect(route.amountIn == 1_000_000)
    }

    @Test func buildsTheRoutersCallAsTheSDKDoes() throws {
        let call = try Swap.call(for: try route(), sender: try StacksAddress(Self.sender))
        #expect(call.functionName == "swap-4")
        #expect(call.arguments.map { "0x" + $0.serialized.hex } == Self.sdkArguments)
        #expect(call.postConditions.map { $0.serialized.hex } == Self.sdkPostConditions)
    }

    @Test func encodesAHopTuple() throws {
        let pool = try Principal(try route().hops[0].vault.contractId)
        let tuple = ClarityValue.tuple(["opcode": .some(.buffer(Data(count: 16))), "pool": .principal(pool)])
        #expect("0x" + tuple.serialized.hex == Self.sdkTuple)
    }

    @Test func encodesThePostConditionsTheSDKEncodes() throws {
        let sender = try StacksAddress(Self.sender)
        let stx = PostCondition.stx(principal: .standard(sender), code: .lessOrEqual, amount: 5)
        #expect("0x" + stx.serialized.hex == Self.sdkStxLessOrEqual5)
        let token = try StacksAddress("SP2ZNGJ85ENDY6QRHQ5P2D4FXKGZWCKTB2T0Z55KS")
        let ft = PostCondition.fungible(principal: .standard(sender), token: token, tokenName: "token-a", asset: "token-a", code: .lessOrEqual, amount: 5)
        #expect("0x" + ft.serialized.hex == Self.sdkFtLessOrEqual5)
    }
